mapper.select:
SELECT it.*
FROM item_target it
WHERE it.item_id = #{itemId}

mapper.insert:
INSERT INTO item_target
	(item_id, target, previous_path, published_commit_id, last_published_on)
SELECT i.id, #{target}, null, #{commitId}, #{timestamp}
FROM item i
WHERE i.site_id = #{siteId}
  AND i.path NOT IN (SELECT pi.path
		     FROM publish_item pi
		     WHERE pi.package_id = #{packageId}
		       AND (pi.publish_state & #{itemFailureState}) > 0)

mapper.delete:
DELETE it
FROM item_target it
	INNER JOIN item i ON i.id = it.item_id
WHERE i.site_id = #{siteId}
  AND it.target = #{target}

mapper.select:
SELECT COUNT(1) > 0
FROM item_target it
	INNER JOIN item i ON i.id = it.item_id
WHERE i.site_id = #{siteId}
  AND it.target = #{target}

SELECT it.*, i.path
FROM item_target it INNER JOIN item i ON it.item_id = i.id
WHERE i.site_id = #{siteId}
AND i.path IN

	#{path}
